import{t,translateUi}from './i18n.js';
import{getDevicePosition}from './city-location.js';
import{personalDataAllowed}from './audience.js';
import{esc,modal,toast}from './ui.js';
import{localCities,searchCities,locateCity,latestRequest}from './city-data.js';
export function openCityDialog(currentCity,onSelect){
 modal('<div class="modal-head"><h2 data-i18n="cityUi.title">'+esc(t('cityUi.title'))+'</h2><button class="icon-button" data-close data-i18n="common.close" data-i18n-aria-label="common.close" aria-label="'+esc(t('common.close'))+'">×</button></div><form id="city-search"><div class="field"><label for="city-name" data-i18n="cityUi.city">'+esc(t('cityUi.city'))+'</label><input id="city-name" data-i18n-placeholder="cityUi.example" placeholder="'+esc(t('cityUi.example'))+'" required minlength="2" maxlength="120" autocomplete="off" aria-controls="city-results"></div><div id="city-results" data-i18n-aria-label="cityUi.suggestions" aria-label="'+esc(t('cityUi.suggestions'))+'"></div><p id="city-status" class="muted city-status" role="status"></p><button class="button" data-i18n="cityUi.find">'+esc(t('cityUi.find'))+'</button></form><button class="button secondary city-geolocate" id="geolocate" data-i18n="cityUi.locate">'+esc(t('cityUi.locate'))+'</button><p class="city-privacy-note" data-i18n="cityUi.privacyNote">'+esc(t('cityUi.privacyNote'))+'</p><details class="city-privacy"><summary data-i18n="cityUi.aboutLocation">'+esc(t('cityUi.aboutLocation'))+'</summary><p data-i18n="cityUi.privacyDetails">'+esc(t('cityUi.privacyDetails'))+'</p><a href="https://www.bigdatacloud.com/privacy-policy" target="_blank" rel="noopener" data-i18n="cityUi.privacyLink">'+esc(t('cityUi.privacyLink'))+'</a><p data-i18n="cityUi.searchProvider">'+esc(t('cityUi.searchProvider'))+'</p></details>');
 const dialog=document.getElementById('modal'),form=document.getElementById('city-search'),input=document.getElementById('city-name'),results=document.getElementById('city-results'),status=document.getElementById('city-status'),geo=document.getElementById('geolocate');
 const requests=latestRequest();let timer,closed=false;
 const setText=(node,key)=>{if(key)node.setAttribute('data-i18n',key);else node.removeAttribute('data-i18n');node.textContent=key?t(key):'';};translateUi(dialog);
 const active=()=>!closed&&dialog.open&&input.isConnected;
 const cancel=()=>{clearTimeout(timer);requests.cancel();geo.disabled=false;setText(geo,'cityUi.locate')};
 if(!personalDataAllowed()){geo.hidden=true;for(const note of dialog.querySelectorAll('.city-privacy-note,.city-privacy'))note.hidden=true;}
 const cleanup=()=>{closed=true;cancel()};dialog.addEventListener('close',cleanup,{once:true});
 const select=city=>{if(!active())return;input.value=city.name;cancel();onSelect(city)};
 function show(cities){results.replaceChildren();for(const city of cities){const button=document.createElement('button');button.type='button';button.className='list-button city-suggestion';const same=cities.filter(other=>other.name.toLocaleLowerCase('ru')===city.name.toLocaleLowerCase('ru')).length>1;button.innerHTML='<span>'+esc(city.name)+'</span>'+(same?'<small>'+esc([city.country,city.admin1].filter(Boolean).join(' · '))+'</small>':'');button.onclick=()=>select(city);results.append(button)}}
 async function search(query,request,local){try{const found=await searchCities(query,{signal:request.signal});if(!active()||!request.current())return;const cities=found.length?found:local;show(cities);setText(status,cities.length?'':query.length===2?'cityUi.oneMoreLetter':'cityUi.notFound')}catch{if(!active()||!request.current())return;show(local);setText(status,local.length?'cityUi.offlineSaved':'cityUi.searchFailed')}}
 function changed(immediate=false){cancel();const query=input.value.trim(),request=requests.start(),local=localCities(query,currentCity);show(local);setText(status,'');if(query.length<2)return;if(!immediate&&query.length===2){setText(status,'cityUi.fullSearchLetter');return}show([]);setText(status,'cityUi.searching');if(immediate)search(query,request,local);else timer=setTimeout(()=>search(query,request,local),300)}
 input.addEventListener('compositionstart',cancel);input.addEventListener('input',event=>{if(!event.isComposing)changed()});input.addEventListener('compositionend',()=>changed());input.addEventListener('keydown',event=>{if(event.key==='ArrowDown'&&results.firstElementChild){event.preventDefault();results.firstElementChild.focus()}});results.addEventListener('keydown',event=>{if(!['ArrowDown','ArrowUp'].includes(event.key))return;event.preventDefault();const buttons=[...results.children],index=buttons.indexOf(document.activeElement);if(event.key==='ArrowUp'&&index===0)input.focus();else buttons[Math.max(0,Math.min(buttons.length-1,index+(event.key==='ArrowDown'?1:-1)))]?.focus()});form.onsubmit=event=>{event.preventDefault();changed(true)};
 geo.onclick=async()=>{if(!personalDataAllowed())return;if(!navigator.geolocation){toast(t('cityUi.unavailable'));return}cancel();const request=requests.start();geo.disabled=true;setText(geo,'cityUi.locating');setText(status,'');let coordinatesReceived=false;try{const position=await getDevicePosition({signal:request.signal});if(!active()||!request.current())return;coordinatesReceived=true;setText(geo,'cityUi.finding');const city=await locateCity(position.coords,{signal:request.signal});if(active()&&request.current())select(city)}catch(error){if(!active()||!request.current())return;geo.disabled=false;setText(geo,'cityUi.locate');setText(status,coordinatesReceived?'cityUi.coordinatesOnly':error.code===1?'cityUi.denied':'cityUi.noCoordinates')}};
}
